#!/usr/bin/env bash
set -euo pipefail

# ===========================================================================
# rollout_staging.sh - EcoAir Copilot Skills Staging Rollout Script
#
# Deploys validated Copilot skill manifests to the staging environment.
# Supports staging-first deployment with optional promotion to production.
#
# Usage:
#   bash scripts/rollout_staging.sh [OPTIONS]
#
# Options:
#   --help          Show this help message
#   --promote       Promote current staging to production
#   --prod          Alias for --promote
#   --skip-tests    Skip test suite (not recommended)
#   --dry-run       Show what would happen without executing
#   --verbose       Enable verbose output
#   --tag TAG       Deploy a specific git tag (default: current branch HEAD)
# ===========================================================================

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_ROOT="$(cd "$SCRIPT_DIR/.." && pwd)"
MANIFESTS_DIR="$PROJECT_ROOT/manifests"

# --- Configuration (override via environment variables) ---
STAGING_BRANCH="${STAGING_BRANCH:-staging}"
PROD_BRANCH="${PROD_BRANCH:-main}"
DEPLOY_TARGET_STAGING="${DEPLOY_TARGET_STAGING:-}"
DEPLOY_TARGET_PROD="${DEPLOY_TARGET_PROD:-}"
HEALTH_CHECK_URL_STAGING="${HEALTH_CHECK_URL_STAGING:-}"
HEALTH_CHECK_URL_PROD="${HEALTH_CHECK_URL_PROD:-}"
HEALTH_CHECK_TIMEOUT="${HEALTH_CHECK_TIMEOUT:-30}"

# --- Color Output ---
RED='\033[0;31m'
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
BLUE='\033[0;34m'
NC='\033[0m' # No Color

# --- Flags ---
PROMOTE=false
SKIP_TESTS=false
DRY_RUN=false
VERBOSE=false
DEPLOY_TAG=""

# ===========================================================================
# Functions
# ===========================================================================

usage() {
  cat <<EOF
  EcoAir Copilot Skills - Staging Rollout Script

  USAGE:
    bash scripts/rollout_staging.sh [OPTIONS]

    OPTIONS:
      --help          Show this help message and exit
        --promote       Promote current staging build to production
          --prod          Alias for --promote
            --skip-tests    Skip running the test suite (not recommended)
              --dry-run       Preview actions without executing them
                --verbose       Enable verbose logging
                  --tag TAG       Deploy a specific git tag

                  ENVIRONMENT VARIABLES:
                    STAGING_BRANCH            Git branch for staging (default: staging)
                      PROD_BRANCH               Git branch for production (default: main)
                        DEPLOY_TARGET_STAGING     Staging deployment target (URL or path)
                          DEPLOY_TARGET_PROD        Production deployment target (URL or path)
                            HEALTH_CHECK_URL_STAGING  URL to check after staging deploy
                              HEALTH_CHECK_URL_PROD     URL to check after production deploy
                                HEALTH_CHECK_TIMEOUT      Timeout in seconds for health checks (default: 30)

                                EXAMPLES:
                                  # Deploy to staging
                                    bash scripts/rollout_staging.sh

                                      # Dry run (preview only)
                                        bash scripts/rollout_staging.sh --dry-run

                                          # Promote staging to production
                                            bash scripts/rollout_staging.sh --promote

                                              # Deploy specific tag to staging
                                                bash scripts/rollout_staging.sh --tag v1.2.0
                                                EOF
                                                  exit 0
                                                  }

                                                  log() {
                                                    echo -e "${BLUE}[INFO]${NC}  $*"
                                                    }

                                                    log_success() {
                                                      echo -e "${GREEN}[OK]${NC}    $*"
                                                      }

                                                      log_warn() {
                                                        echo -e "${YELLOW}[WARN]${NC}  $*"
                                                        }

                                                        log_error() {
                                                          echo -e "${RED}[ERROR]${NC} $*"
                                                          }

                                                          log_step() {
                                                            echo ""
                                                              echo -e "${BLUE}========================================${NC}"
                                                                echo -e "${BLUE}  $*${NC}"
                                                                  echo -e "${BLUE}========================================${NC}"
                                                                  }

                                                                  verbose() {
                                                                    if [ "$VERBOSE" = true ]; then
                                                                        echo -e "${BLUE}[DEBUG]${NC} $*"
                                                                          fi
                                                                          }

                                                                          die() {
                                                                            log_error "$@"
                                                                              exit 1
                                                                              }

                                                                              # --- Preflight Checks ---
                                                                              preflight_checks() {
                                                                                log_step "PREFLIGHT CHECKS"

                                                                                  # Check we are in a git repo
                                                                                    if ! git rev-parse --is-inside-work-tree >/dev/null 2>&1; then
                                                                                        die "Not inside a git repository"
                                                                                          fi
                                                                                            log_success "Inside git repository"

                                                                                              # Check Node.js is available
                                                                                                if ! command -v node >/dev/null 2>&1; then
                                                                                                    die "Node.js is required but not found. Install Node.js >= 18"
                                                                                                      fi
                                                                                                        local node_version
                                                                                                          node_version=$(node --version)
                                                                                                            log_success "Node.js found: $node_version"
                                                                                                            
                                                                                                              # Check manifests directory exists
                                                                                                                if [ ! -d "$MANIFESTS_DIR" ]; then
                                                                                                                    die "Manifests directory not found: $MANIFESTS_DIR"
                                                                                                                      fi
                                                                                                                        local manifest_count
                                                                                                                          manifest_count=$(find "$MANIFESTS_DIR" -name "*-manifest.json" | wc -l | tr -d ' ')
                                                                                                                            log_success "Found $manifest_count manifest file(s)"
                                                                                                                            
                                                                                                                              # Check git working tree is clean
                                                                                                                                if [ -n "$(git status --porcelain 2>/dev/null)" ]; then
                                                                                                                                    log_warn "Git working tree has uncommitted changes"
                                                                                                                                        if [ "$DRY_RUN" = false ]; then
                                                                                                                                              read -rp "Continue anyway? (y/N): " confirm
                                                                                                                                                    if [[ ! "$confirm" =~ ^[Yy]$ ]]; then
                                                                                                                                                            die "Aborted: clean your working tree first"
                                                                                                                                                                  fi
                                                                                                                                                                      fi
                                                                                                                                                                        else
                                                                                                                                                                            log_success "Git working tree is clean"
                                                                                                                                                                              fi
                                                                                                                                                                              
                                                                                                                                                                                # Display current branch/tag info
                                                                                                                                                                                  local current_branch
                                                                                                                                                                                    current_branch=$(git rev-parse --abbrev-ref HEAD 2>/dev/null || echo "detached")
                                                                                                                                                                                      local current_sha
                                                                                                                                                                                        current_sha=$(git rev-parse --short HEAD 2>/dev/null || echo "unknown")
                                                                                                                                                                                          log "Current branch: $current_branch ($current_sha)"
                                                                                                                                                                                          
                                                                                                                                                                                            if [ -n "$DEPLOY_TAG" ]; then
                                                                                                                                                                                                if ! git rev-parse "$DEPLOY_TAG" >/dev/null 2>&1; then
                                                                                                                                                                                                      die "Tag '$DEPLOY_TAG' does not exist"
                                                                                                                                                                                                          fi
                                                                                                                                                                                                              log "Deploy tag: $DEPLOY_TAG"
                                                                                                                                                                                                                fi
                                                                                                                                                                                                                
                                                                                                                                                                                                                  # Check required env vars for deployment targets
                                                                                                                                                                                                                    if [ "$PROMOTE" = true ] && [ -z "$DEPLOY_TARGET_PROD" ]; then
                                                                                                                                                                                                                        log_warn "DEPLOY_TARGET_PROD is not set. Production deploy will be simulated."
                                                                                                                                                                                                                          fi
                                                                                                                                                                                                                            if [ "$PROMOTE" = false ] && [ -z "$DEPLOY_TARGET_STAGING" ]; then
                                                                                                                                                                                                                                log_warn "DEPLOY_TARGET_STAGING is not set. Staging deploy will be simulated."
                                                                                                                                                                                                                                  fi
                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                  # --- Run Tests ---
                                                                                                                                                                                                                                  run_tests() {
                                                                                                                                                                                                                                    log_step "RUNNING TESTS"
                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                      if [ "$SKIP_TESTS" = true ]; then
                                                                                                                                                                                                                                          log_warn "Tests skipped (--skip-tests flag)"
                                                                                                                                                                                                                                              return 0
                                                                                                                                                                                                                                                fi
                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                  # Install dependencies if needed
                                                                                                                                                                                                                                                    if [ ! -d "$PROJECT_ROOT/node_modules" ]; then
                                                                                                                                                                                                                                                        log "Installing dependencies..."
                                                                                                                                                                                                                                                            if [ "$DRY_RUN" = true ]; then
                                                                                                                                                                                                                                                                  log "[DRY RUN] Would run: npm install"
                                                                                                                                                                                                                                                                      else
                                                                                                                                                                                                                                                                            cd "$PROJECT_ROOT" && npm install --no-audit --no-fund
                                                                                                                                                                                                                                                                                fi
                                                                                                                                                                                                                                                                                  fi
                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                    # Run manifest validation
                                                                                                                                                                                                                                                                                      log "Validating manifests..."
                                                                                                                                                                                                                                                                                        if [ "$DRY_RUN" = true ]; then
                                                                                                                                                                                                                                                                                            log "[DRY RUN] Would run: node scripts/validate-manifests.js"
                                                                                                                                                                                                                                                                                              else
                                                                                                                                                                                                                                                                                                  node "$SCRIPT_DIR/validate-manifests.js" || die "Manifest validation failed"
                                                                                                                                                                                                                                                                                                    fi
                                                                                                                                                                                                                                                                                                      log_success "Manifest validation passed"
                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                        # Run unit tests
                                                                                                                                                                                                                                                                                                          log "Running unit tests..."
                                                                                                                                                                                                                                                                                                            if [ "$DRY_RUN" = true ]; then
                                                                                                                                                                                                                                                                                                                log "[DRY RUN] Would run: npm test"
                                                                                                                                                                                                                                                                                                                  else
                                                                                                                                                                                                                                                                                                                      cd "$PROJECT_ROOT" && npm test || die "Unit tests failed"
                                                                                                                                                                                                                                                                                                                        fi
                                                                                                                                                                                                                                                                                                                          log_success "All tests passed"
                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                                                                                          # --- Build/Package Step ---
                                                                                                                                                                                                                                                                                                                          build_package() {
                                                                                                                                                                                                                                                                                                                            log_step "BUILD / PACKAGE"
                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                              local build_dir="$PROJECT_ROOT/.build"
                                                                                                                                                                                                                                                                                                                                local timestamp
                                                                                                                                                                                                                                                                                                                                  timestamp=$(date +%Y%m%d-%H%M%S)
                                                                                                                                                                                                                                                                                                                                    local build_id="ecoair-skills-$timestamp"
                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                      if [ "$DRY_RUN" = true ]; then
                                                                                                                                                                                                                                                                                                                                          log "[DRY RUN] Would create build package: $build_id"
                                                                                                                                                                                                                                                                                                                                              log "[DRY RUN] Would copy manifests to $build_dir/$build_id/"
                                                                                                                                                                                                                                                                                                                                                  return 0
                                                                                                                                                                                                                                                                                                                                                    fi
                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                      mkdir -p "$build_dir/$build_id/manifests"
                                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                                        # Copy manifests
                                                                                                                                                                                                                                                                                                                                                          cp "$MANIFESTS_DIR"/*-manifest.json "$build_dir/$build_id/manifests/"
                                                                                                                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                                                                                                                            # Create build metadata
                                                                                                                                                                                                                                                                                                                                                              cat > "$build_dir/$build_id/build-info.json" <<BUILDEOF
                                                                                                                                                                                                                                                                                                                                                              {
                                                                                                                                                                                                                                                                                                                                                                "buildId": "$build_id",
                                                                                                                                                                                                                                                                                                                                                                  "timestamp": "$(date -u +%Y-%m-%dT%H:%M:%SZ)",
                                                                                                                                                                                                                                                                                                                                                                    "gitBranch": "$(git rev-parse --abbrev-ref HEAD 2>/dev/null || echo 'unknown')",
                                                                                                                                                                                                                                                                                                                                                                      "gitSha": "$(git rev-parse HEAD 2>/dev/null || echo 'unknown')",
                                                                                                                                                                                                                                                                                                                                                                        "gitTag": "$DEPLOY_TAG",
                                                                                                                                                                                                                                                                                                                                                                          "manifestCount": $(find "$build_dir/$build_id/manifests" -name "*.json" | wc -l | tr -d ' ')
                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                          BUILDEOF
                                                                                                                                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                                                                                                                                            log_success "Build package created: $build_dir/$build_id"
                                                                                                                                                                                                                                                                                                                                                                              log "  Manifests: $(ls "$build_dir/$build_id/manifests/" | wc -l | tr -d ' ') files"
                                                                                                                                                                                                                                                                                                                                                                                echo "$build_id" > "$build_dir/latest-build"
                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                # --- Deploy to Staging ---
                                                                                                                                                                                                                                                                                                                                                                                deploy_staging() {
                                                                                                                                                                                                                                                                                                                                                                                  log_step "DEPLOY TO STAGING"
                                                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                    if [ "$DRY_RUN" = true ]; then
                                                                                                                                                                                                                                                                                                                                                                                        log "[DRY RUN] Would deploy to staging"
                                                                                                                                                                                                                                                                                                                                                                                            if [ -n "$DEPLOY_TARGET_STAGING" ]; then
                                                                                                                                                                                                                                                                                                                                                                                                  log "[DRY RUN] Target: $DEPLOY_TARGET_STAGING"
                                                                                                                                                                                                                                                                                                                                                                                                      fi
                                                                                                                                                                                                                                                                                                                                                                                                          return 0
                                                                                                                                                                                                                                                                                                                                                                                                            fi
                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                              if [ -n "$DEPLOY_TARGET_STAGING" ]; then
                                                                                                                                                                                                                                                                                                                                                                                                                  log "Deploying to staging: $DEPLOY_TARGET_STAGING"
                                                                                                                                                                                                                                                                                                                                                                                                                      # Copy build artifacts to staging target
                                                                                                                                                                                                                                                                                                                                                                                                                          local build_dir="$PROJECT_ROOT/.build"
                                                                                                                                                                                                                                                                                                                                                                                                                              local latest_build
                                                                                                                                                                                                                                                                                                                                                                                                                                  latest_build=$(cat "$build_dir/latest-build" 2>/dev/null || echo "")
                                                                                                                                                                                                                                                                                                                                                                                                                                      if [ -z "$latest_build" ]; then
                                                                                                                                                                                                                                                                                                                                                                                                                                            die "No build found. Run build step first."
                                                                                                                                                                                                                                                                                                                                                                                                                                                fi
                                                                                                                                                                                                                                                                                                                                                                                                                                                    verbose "Deploying build: $latest_build"
                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                        # rsync/copy to staging target (supports local path or rsync target)
                                                                                                                                                                                                                                                                                                                                                                                                                                                            if [[ "$DEPLOY_TARGET_STAGING" == rsync://* ]] || [[ "$DEPLOY_TARGET_STAGING" == *:* ]]; then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  rsync -avz --delete "$build_dir/$latest_build/" "$DEPLOY_TARGET_STAGING/" || die "rsync to staging failed"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      else
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            mkdir -p "$DEPLOY_TARGET_STAGING"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  cp -r "$build_dir/$latest_build/"* "$DEPLOY_TARGET_STAGING/" || die "copy to staging failed"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      fi
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          log_success "Deployed to staging"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            else
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                log_warn "DEPLOY_TARGET_STAGING not configured - simulating deploy"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    log "In production use, set DEPLOY_TARGET_STAGING to your staging path/URL"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        log_success "Staging deploy simulated successfully"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          fi
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          # --- Smoke Tests ---
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          smoke_tests() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            log_step "SMOKE TESTS"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if [ "$DRY_RUN" = true ]; then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  log "[DRY RUN] Would run smoke tests"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return 0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        fi
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          # Test 1: Validate build artifact exists
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            local build_dir="$PROJECT_ROOT/.build"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              local latest_build
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                latest_build=$(cat "$build_dir/latest-build" 2>/dev/null || echo "")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if [ -n "$latest_build" ] && [ -f "$build_dir/$latest_build/build-info.json" ]; then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      log_success "Build artifact exists and contains build-info.json"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        else
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            log_warn "Build artifact check skipped (simulated deploy)"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              fi
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                # Test 2: Validate all manifests are valid JSON in the build
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if [ -n "$latest_build" ] && [ -d "$build_dir/$latest_build/manifests" ]; then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      local json_errors=0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          for f in "$build_dir/$latest_build/manifests"/*.json; do
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if ! node -e "JSON.parse(require('fs').readFileSync('$f','utf-8'))" 2>/dev/null; then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        log_error "Invalid JSON: $(basename "$f")"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                json_errors=$((json_errors + 1))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      fi
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          done
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if [ "$json_errors" -eq 0 ]; then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    log_success "All manifests in build are valid JSON"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        else
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              die "$json_errors manifest(s) have invalid JSON in build artifact"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  fi
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    fi
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      # Test 3: Health check endpoint (if configured)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        local health_url=""
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if [ "$PROMOTE" = true ] && [ -n "$HEALTH_CHECK_URL_PROD" ]; then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              health_url="$HEALTH_CHECK_URL_PROD"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                elif [ -n "$HEALTH_CHECK_URL_STAGING" ]; then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    health_url="$HEALTH_CHECK_URL_STAGING"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      fi
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if [ -n "$health_url" ]; then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            log "Checking health endpoint: $health_url"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                local http_code
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    http_code=$(curl -s -o /dev/null -w "%{http_code}" --connect-timeout "$HEALTH_CHECK_TIMEOUT" "$health_url" 2>/dev/null || echo "000")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if [ "$http_code" -ge 200 ] && [ "$http_code" -lt 300 ]; then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              log_success "Health check passed (HTTP $http_code)"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  else
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        die "Health check failed (HTTP $http_code). URL: $health_url"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            fi
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              else
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  log_warn "No health check URL configured - skipping endpoint check"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      log "Set HEALTH_CHECK_URL_STAGING or HEALTH_CHECK_URL_PROD for live checks"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        fi
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          # Test 4: Re-validate manifests from source
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            log "Re-validating source manifests..."
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              node "$SCRIPT_DIR/validate-manifests.js" || die "Post-deploy manifest validation failed"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                log_success "Post-deploy validation passed"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  log_success "All smoke tests passed"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  # --- Promote to Production ---
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  promote_to_prod() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    log_step "PROMOTE TO PRODUCTION"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      echo ""
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        echo -e "${YELLOW}=== PRODUCTION DEPLOYMENT SUMMARY ===${NC}"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          echo "  Branch:    $(git rev-parse --abbrev-ref HEAD 2>/dev/null || echo 'unknown')"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            echo "  SHA:       $(git rev-parse --short HEAD 2>/dev/null || echo 'unknown')"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              echo "  Tag:       ${DEPLOY_TAG:-none}"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                echo "  Manifests: $(find "$MANIFESTS_DIR" -name "*-manifest.json" | wc -l | tr -d ' ') files"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  echo "  Target:    ${DEPLOY_TARGET_PROD:-simulated}"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    echo ""
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if [ "$DRY_RUN" = true ]; then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          log "[DRY RUN] Would promote to production"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return 0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                fi
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  read -rp "Proceed with production deployment? (yes/NO): " confirm
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if [ "$confirm" != "yes" ]; then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        die "Production deploy aborted by user"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          fi
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if [ -n "$DEPLOY_TARGET_PROD" ]; then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                log "Deploying to production: $DEPLOY_TARGET_PROD"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    local build_dir="$PROJECT_ROOT/.build"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        local latest_build
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            latest_build=$(cat "$build_dir/latest-build" 2>/dev/null || echo "")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if [ -z "$latest_build" ]; then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      die "No build found. Run staging deploy first."
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          fi
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if [[ "$DEPLOY_TARGET_PROD" == rsync://* ]] || [[ "$DEPLOY_TARGET_PROD" == *:* ]]; then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    rsync -avz --delete "$build_dir/$latest_build/" "$DEPLOY_TARGET_PROD/" || die "rsync to production failed"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        else
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              mkdir -p "$DEPLOY_TARGET_PROD"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    cp -r "$build_dir/$latest_build/"* "$DEPLOY_TARGET_PROD/" || die "copy to production failed"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        fi
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            log_success "Deployed to production"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              else
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  log_warn "DEPLOY_TARGET_PROD not configured - simulating production deploy"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      log_success "Production deploy simulated"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        fi
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        # ===========================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        # Parse Arguments
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        # ===========================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        while [[ $# -gt 0 ]]; do
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          case $1 in
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              --help|-h)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    usage
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ;;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              --promote|--prod)
